# 独立期望来自 PG16 Table 13.3，而非从待验证 SQL 结果反推。
CONFLICTS = {
    RowLockMode.KEY_SHARE: {RowLockMode.UPDATE},
    RowLockMode.SHARE: {RowLockMode.NO_KEY_UPDATE, RowLockMode.UPDATE},
    RowLockMode.NO_KEY_UPDATE: {RowLockMode.SHARE, RowLockMode.NO_KEY_UPDATE, RowLockMode.UPDATE},
    RowLockMode.UPDATE: set(RowLockMode),
}


def lock_row(connection: psycopg.Connection, mode: RowLockMode, *, nowait: bool = False) -> None:
    """对实验行取显式行锁；SQL 片段只来自封闭枚举和固定后缀。"""
    query = sql.SQL("SELECT id FROM probe_rows WHERE id = 1 FOR {}{}").format(
        sql.SQL(mode.sql), sql.SQL(" NOWAIT" if nowait else "")
    )
    assert connection.execute(query).fetchone() == (1,)


@pytest.mark.parametrize(("held", "requested"), list(product(RowLockMode, repeat=2)))
def test_row_lock_conflict_matrix(postgres_probe: PostgresProbe, held: RowLockMode, requested: RowLockMode) -> None:
    """两个独立 backend 穷举四种模式的 16 对；冲突必须返回 55P03。"""
    holder, contender = postgres_probe.connect(), postgres_probe.connect()
    assert holder.info.backend_pid != contender.info.backend_pid
    with holder.transaction():
        lock_row(holder, held)
        if requested in CONFLICTS[held]:
            with pytest.raises(psycopg.errors.LockNotAvailable) as error:
                with contender.transaction():
                    lock_row(contender, requested, nowait=True)
            assert error.value.sqlstate == "55P03"
            assert contender.info.transaction_status == TransactionStatus.IDLE
        else:
            with contender.transaction():
                lock_row(contender, requested, nowait=True)


def test_non_key_update_does_not_replace_explicit_update_barrier(postgres_probe: PostgresProbe) -> None:
    """普通非键 UPDATE 不阻塞 KEY SHARE，不能冒充永久撤回的 FOR UPDATE。"""
    writer, reader = postgres_probe.connect(), postgres_probe.connect()
    with writer.transaction():
        writer.execute("UPDATE probe_rows SET value = 1 WHERE id = 1")
        with reader.transaction():
            lock_row(reader, RowLockMode.KEY_SHARE, nowait=True)
        with pytest.raises(psycopg.errors.LockNotAvailable):
            with reader.transaction():
                lock_row(reader, RowLockMode.UPDATE, nowait=True)


def test_skip_locked_only_skips_currently_locked_candidates(postgres_probe: PostgresProbe) -> None:
    """被锁的队首不会阻塞候选扫描；本实验不将它当作同键 FIFO 的证明。"""
    holder, candidate = postgres_probe.connect(), postgres_probe.connect()
    query = "SELECT id FROM probe_rows ORDER BY id LIMIT 1 FOR UPDATE SKIP LOCKED"
    with holder.transaction():
        lock_row(holder, RowLockMode.UPDATE)
        with candidate.transaction():
            assert candidate.execute(query).fetchone() == (2,)
    with candidate.transaction():
        assert candidate.execute(query).fetchone() == (1,)


@pytest.mark.parametrize("commit", [True, False])
def test_set_local_does_not_escape_transaction(postgres_probe: PostgresProbe, commit: bool) -> None:
    """提交和回滚都恢复原配置，验证未来连接池可采用的事务局部设置。"""
    connection = postgres_probe.connect()
    baseline = connection.execute("SHOW lock_timeout").fetchone()
    with connection.transaction(force_rollback=not commit):
        connection.execute("SET LOCAL lock_timeout = '250ms'")
        assert connection.execute("SHOW lock_timeout").fetchone() == ("250ms",)
    assert connection.execute("SHOW lock_timeout").fetchone() == baseline


def test_read_committed_refreshes_after_waiting_for_lock(postgres_probe: PostgresProbe) -> None:
    """等待锁前的汇总为旧值，拿锁后独立语句能读取新提交流水。"""
    writer, reader, observer = (postgres_probe.connect() for _ in range(3))
    before_lock = PausePoint("before-read-committed-lock")

    def read_totals() -> tuple[int, int]:
        """先读旧快照，再等待写者的锁，最后重新汇总。"""
        with reader.transaction():
            old = reader.execute("SELECT sum(value) FROM probe_rows").fetchone()[0]
            before_lock.hit()
            lock_row(reader, RowLockMode.UPDATE)
            new = reader.execute("SELECT sum(value) FROM probe_rows").fetchone()[0]
            return old, new

    with ThreadPoolExecutor(max_workers=1) as executor:
        try:
            with writer.transaction():
                writer.execute("UPDATE probe_rows SET value = 1 WHERE id = 1")
                writer.execute("UPDATE probe_rows SET value = 9 WHERE id = 2")
                future = executor.submit(read_totals)
                before_lock.wait_until_reached()
                before_lock.resume()
                wait_for_blocker(observer, reader.info.backend_pid, writer.info.backend_pid)
            assert future.result(timeout=15) == (0, 10)
        finally:
            before_lock.resume()


def test_deadlock_rolls_back_and_retries_whole_transaction(postgres_probe: PostgresProbe) -> None:
    """真实制造等待环，捕获 40P01，重试后只保留每个事务的一次有效写入。"""
    first, second, observer = (postgres_probe.connect() for _ in range(3))
    first_locked = PausePoint("first-worker-holds-row-1")
    second_locked = PausePoint("second-worker-holds-row-2")

    def work(connection: psycopg.Connection, name: str, rows: tuple[int, int], point: PausePoint) -> tuple[int, list[str]]:
        """实验性重试：异常在事务上下文外捕获，确保完整回滚而非重试单条 SQL。"""
        deadlocks = []
        for attempt in range(2):
            try:
                with connection.transaction():
                    connection.execute("INSERT INTO probe_effects (worker) VALUES (%s)", (name,))
                    connection.execute("UPDATE probe_rows SET value = value + 1 WHERE id = %s", (rows[0],))
                    if attempt == 0:
                        point.hit()
                    connection.execute("UPDATE probe_rows SET value = value + 1 WHERE id = %s", (rows[1],))
                return attempt + 1, deadlocks
            except psycopg.errors.DeadlockDetected as error:
                assert connection.info.transaction_status == TransactionStatus.IDLE
                deadlocks.append(error.sqlstate)
        raise AssertionError("Deadlock experiment exceeded its retry budget")

    with ThreadPoolExecutor(max_workers=2) as executor:
        first_result = executor.submit(work, first, "first", (1, 2), first_locked)
        second_result = executor.submit(work, second, "second", (2, 1), second_locked)
        try:
            first_locked.wait_until_reached()
            second_locked.wait_until_reached()
            first_locked.resume()
            wait_for_blocker(observer, first.info.backend_pid, second.info.backend_pid)
            second_locked.resume()
            results = [first_result.result(timeout=20), second_result.result(timeout=20)]
        finally:
            first_locked.resume()
            second_locked.resume()
    assert sorted(attempts for attempts, _ in results) == [1, 2]
    assert [code for _, codes in results for code in codes] == ["40P01"]
    assert observer.execute("SELECT id, value FROM probe_rows WHERE id IN (1, 2) ORDER BY id").fetchall() == [(1, 2), (2, 2)]
    assert observer.execute("SELECT worker FROM probe_effects ORDER BY worker").fetchall() == [("first",), ("second",)]


def test_sorted_guarded_locks_complete_without_deadlock(postgres_probe: PostgresProbe) -> None:
    """相同竞争由统一锁序处理时只等待，不形成等待环或重复写入。"""
    first, second, observer = (postgres_probe.connect() for _ in range(3))
    first_locked = PausePoint("ordered-first-worker-holds-row-1")
    second_ready = PausePoint("ordered-second-worker-before-row-1")

    def work(connection: psycopg.Connection, name: str, is_first: bool) -> None:
        """每次事务新建守卫；显式 SQL 前按相同的规范化顺序登记。"""
        guard = LockOrderGuard()
        with connection.transaction():
            if not is_first:
                second_ready.hit()
            for row in (1, 2):
                guard.before_lock(LockStage.CONTROL_OBJECT, ("document", str(row)), RowLockMode.UPDATE)
                connection.execute("SELECT id FROM probe_rows WHERE id = %s FOR UPDATE", (row,))
                if is_first and row == 1:
                    first_locked.hit()
                connection.execute("UPDATE probe_rows SET value = value + 1 WHERE id = %s", (row,))
            connection.execute("INSERT INTO probe_effects (worker) VALUES (%s)", (name,))

    with ThreadPoolExecutor(max_workers=2) as executor:
        first_result = executor.submit(work, first, "first", True)
        second_result = executor.submit(work, second, "second", False)
        try:
            first_locked.wait_until_reached()
            second_ready.wait_until_reached()
            second_ready.resume()
            wait_for_blocker(observer, second.info.backend_pid, first.info.backend_pid)
            first_locked.resume()
            first_result.result(timeout=20)
            second_result.result(timeout=20)
        finally:
            first_locked.resume()
            second_ready.resume()
    assert observer.execute("SELECT id, value FROM probe_rows WHERE id IN (1, 2) ORDER BY id").fetchall() == [(1, 2), (2, 2)]
    assert observer.execute("SELECT count(*) FROM probe_effects").fetchone() == (2,)
